        public List<PODetailsForApprove> GetAllPODetailsForApprove(int aiSchoolId, int aiUserId, int aiStatusId)
        {            
            List<PODetailsForApprove> lstPODetailsApprove = new List<PODetailsForApprove>();
            using (SQLServerDbUtility oSQLServerDbUtility = new SQLServerDbUtility())
            {
                oSQLServerDbUtility.AddParameter("SchoolId", aiSchoolId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("UserId", aiUserId, SqlDbType.Int);
                oSQLServerDbUtility.AddParameter("StatusId", aiStatusId, SqlDbType.Int);

                using (SqlDataReader oSqlDataReader = oSQLServerDbUtility.ExecuteStoredProcedureAndGetresult("usp_GetAllPODetailsForApprove"))
                {
                    while (oSqlDataReader.Read())
                    {
                        lstPODetailsApprove.Add(new PODetailsForApprove
                        {
                            POId = Convert.ToInt32(oSqlDataReader["POId"]),
                            UserId = Convert.ToInt32(oSqlDataReader["UserId"]),
                            RequesterName = Convert.ToString(oSqlDataReader["UserName"]),
                            PODate = Convert.ToDateTime(oSqlDataReader["PoDate"]),
                            POCode = Convert.ToString(oSqlDataReader["PurchaseOrderCode"]),
                            RequesterId = Convert.ToInt32(oSqlDataReader["RequesterId"])
                        });
                    }
                }
            }
            return lstPODetailsApprove;
        }

